/** mm between hole centres, and the rule that turns a hole count into a board's size. */
export const PITCH_MM = 20;
export const sizeMm = (holes) => PITCH_MM * (holes + 1);
export const holesFor = (mm) => Math.floor(mm / PITCH_MM) - 1;

